+        "mr", "mrs", "ms", "miss", "mx", "dr", "prof", "professor", "sir", "dame",
+        "lord", "lady", "rev", "reverend", "rt", "hon",
+    ];
+    name.split_whitespace().skip_while(|word| TITLES.contains(word))
+        .collect::<Vec<_>>().join(" ")
+}
+
+fn initials(name: &str, omit_connectives: bool) -> String {
+    const CONNECTIVES: &[&str] = &["a", "an", "and", "for", "in", "of", "on", "the", "to"];
+    name.split_whitespace()
+        .filter(|word| !omit_connectives || !CONNECTIVES.contains(word))
+        .filter_map(|word| word.chars().next()).collect()
