        DeclarationId::new(source.id)?,
        source.parent_interest_id.map(DeclarationId::new).transpose()?,
        source.category.id, source.category.name, latest.register.id, latest.register.published_date,
        latest.registration_date, funding, fetched_at, source_json,
    )?;
    Ok(DeclarationEvidence::new(declaration, declaration_funders, pointer, pointers)?)
}

fn has_funding_anchor(fields: &[SourceField]) -> bool {
    fields.iter().any(|field| matches!(field.name.as_str(), "Value" | "PaymentType"))
}

fn funding_entries(
    fields: &[SourceField], pointer: &str, entries: &mut Vec<CapturedFundingEntry>, pointers: &mut Vec<String>,
) -> Result<(), ApiError> {
    if has_funding_anchor(fields) {
        entries.push(parse_funding_entry(fields, false)?);
        pointers.push(pointer.to_owned());
    }
    for (field_index, field) in fields.iter().enumerate() {
        for (entry_index, nested) in field.values.iter().flatten().enumerate() {
            let pointer = format!("{pointer}/{field_index}/values/{entry_index}");
            if field.name == "Donors" {
                entries.push(parse_funding_entry(nested, true)?);
                pointers.push(pointer);
            } else {
                funding_entries(nested, &pointer, entries, pointers)?;
            }
        }
    }
    Ok(())
}
